"""
Codebase seed — Minimal Flask Todo API (tier 1, good seams)

A single-file Flask app with clean structure: models, routes, error handling.
Designed as a baseline for multi-session stories.
"""

from datetime import datetime, timedelta, timezone
from functools import wraps
import os
import sqlite3

import jwt
from flask import Flask, g, jsonify, request
from werkzeug.security import check_password_hash, generate_password_hash

from tasks import send_notification_email
from repositories import TaskRepository, UserRepository

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "todos.db")
JWT_SECRET = os.environ.get("JWT_SECRET", "development-secret-change-in-production")
JWT_ALGORITHM = "HS256"
JWT_EXPIRATION = timedelta(hours=1)


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    UserRepository(get_db).initialize()
    TaskRepository(get_db).initialize()


def task_repository() -> TaskRepository:
    return TaskRepository(get_db)


def user_repository() -> UserRepository:
    return UserRepository(get_db)


# ── Routes ─────────────────────────────────────────────────────

def create_token(user_id: int) -> str:
    now = datetime.now(timezone.utc)
    return jwt.encode(
        {"sub": str(user_id), "iat": now, "exp": now + JWT_EXPIRATION},
        JWT_SECRET,
        algorithm=JWT_ALGORITHM,
    )


def require_auth(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        authorization = request.headers.get("Authorization", "")
        scheme, _, token = authorization.partition(" ")
        if scheme.lower() != "bearer" or not token:
            return jsonify({"error": "authentication required"}), 401
        try:
            payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGORITHM])
            g.user_id = int(payload["sub"])
        except (jwt.PyJWTError, KeyError, TypeError, ValueError):
            return jsonify({"error": "invalid token"}), 401
        return view(*args, **kwargs)

    return wrapped


@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    email = data.get("email")
    if not isinstance(username, str) or not username.strip():
        return jsonify({"error": "username is required"}), 400
    if not isinstance(password, str) or not password:
        return jsonify({"error": "password is required"}), 400
    if email is not None and (not isinstance(email, str) or not email.strip()):
        return jsonify({"error": "email must be a non-empty string"}), 400

    username = username.strip()
    email = email.strip() if email is not None else None
    try:
        user_id = user_repository().create_user(
            username, generate_password_hash(password), email
        )
    except sqlite3.IntegrityError:
        return jsonify({"error": "username already exists"}), 409
    return jsonify({"id": user_id, "username": username}), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"error": "invalid credentials"}), 401

    user = user_repository().find_by_username(username.strip())
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid credentials"}), 401
    return jsonify({"token": create_token(user["id"])}), 200

@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks():
    return jsonify(task_repository().list_for_owner(g.user_id))


@app.route("/tasks", methods=["POST"])
@require_auth
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    task = task_repository().create_task(title.strip(), g.user_id)
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def show_task(task_id: int):
    task = task_repository().find_for_owner(task_id, g.user_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    status = data.get("status")
    if title is not None and not isinstance(title, str):
        return jsonify({"error": "title must be a string"}), 400
    if isinstance(title, str) and not title.strip():
        return jsonify({"error": "title is required"}), 400
    if status is not None and not isinstance(status, str):
        return jsonify({"error": "status must be a string"}), 400
    repository = task_repository()
    previous_task = repository.find_for_owner(task_id, g.user_id)
    if previous_task is None:
        return jsonify({"error": "task not found"}), 404
    values = {}
    if title is not None:
        values["title"] = title.strip()
    if status is not None:
        values["status"] = status
    task = repository.update_for_owner(task_id, g.user_id, values)
    if previous_task["status"] != "completed" and task["status"] == "completed":
        user_email = user_repository().notification_address(g.user_id)
        if user_email:
            send_notification_email.delay(user_email, task["title"])
    return jsonify(task)


init_db()


if __name__ == "__main__":
    app.run(debug=True)

from abc import ABC
from collections.abc import Callable
from datetime import datetime
import sqlite3


class BaseRepository(ABC):
    """Shared SQLite CRUD primitives for table-specific repositories."""

    table_name: str

    def __init__(self, connection_factory: Callable[[], sqlite3.Connection]):
        self.connection_factory = connection_factory

    def create(self, values: dict) -> int:
        columns = ", ".join(values)
        placeholders = ", ".join("?" for _ in values)
        with self.connection_factory() as conn:
            cursor = conn.execute(
                f"INSERT INTO {self.table_name} ({columns}) VALUES ({placeholders})",
                tuple(values.values()),
            )
            conn.commit()
            return cursor.lastrowid

    def find_one(self, where: dict):
        clause = " AND ".join(f"{column} = ?" for column in where)
        with self.connection_factory() as conn:
            return conn.execute(
                f"SELECT * FROM {self.table_name} WHERE {clause}", tuple(where.values())
            ).fetchone()

    def find_all(self, where: dict | None = None, order_by: str | None = None):
        query = f"SELECT * FROM {self.table_name}"
        parameters = ()
        if where:
            query += " WHERE " + " AND ".join(f"{column} = ?" for column in where)
            parameters = tuple(where.values())
        if order_by:
            query += f" ORDER BY {order_by}"
        with self.connection_factory() as conn:
            return conn.execute(query, parameters).fetchall()

    def update(self, values: dict, where: dict) -> None:
        assignments = ", ".join(f"{column} = ?" for column in values)
        clause = " AND ".join(f"{column} = ?" for column in where)
        with self.connection_factory() as conn:
            conn.execute(
                f"UPDATE {self.table_name} SET {assignments} WHERE {clause}",
                tuple(values.values()) + tuple(where.values()),
            )
            conn.commit()

    def delete(self, where: dict) -> None:
        clause = " AND ".join(f"{column} = ?" for column in where)
        with self.connection_factory() as conn:
            conn.execute(f"DELETE FROM {self.table_name} WHERE {clause}", tuple(where.values()))
            conn.commit()


class TaskRepository(BaseRepository):
    table_name = "tasks"

    def initialize(self) -> None:
        with self.connection_factory() as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS tasks ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                "title TEXT NOT NULL, "
                "status TEXT NOT NULL DEFAULT 'pending', "
                "created_at DATETIME NOT NULL, "
                "owner_id INTEGER REFERENCES users(id))"
            )
            columns = {row["name"] for row in conn.execute("PRAGMA table_info(tasks)")}
            if "owner_id" not in columns:
                conn.execute("ALTER TABLE tasks ADD COLUMN owner_id INTEGER")
            conn.execute("CREATE INDEX IF NOT EXISTS idx_tasks_owner_id ON tasks(owner_id)")

    def create_task(self, title: str, owner_id: int) -> dict:
        now = datetime.utcnow()
        task_id = self.create(
            {"title": title, "status": "pending", "created_at": now, "owner_id": owner_id}
        )
        return {
            "id": task_id,
            "title": title,
            "status": "pending",
            "created_at": now.isoformat(sep=" "),
            "owner_id": owner_id,
        }

    def find_for_owner(self, task_id: int, owner_id: int) -> dict | None:
        row = self.find_one({"id": task_id, "owner_id": owner_id})
        return self._serialize(row) if row else None

    def list_for_owner(self, owner_id: int) -> list[dict]:
        rows = self.find_all(
            {"owner_id": owner_id},
            "CAST(strftime('%s', created_at) AS INTEGER) DESC, id DESC",
        )
        return [self._serialize(row) for row in rows]

    def update_for_owner(self, task_id: int, owner_id: int, values: dict) -> dict | None:
        task = self.find_for_owner(task_id, owner_id)
        if task is None:
            return None
        if values:
            self.update(values, {"id": task_id, "owner_id": owner_id})
        return self.find_for_owner(task_id, owner_id)

    @staticmethod
    def _serialize(row: sqlite3.Row) -> dict:
        task = dict(row)
        if isinstance(task["created_at"], datetime):
            task["created_at"] = task["created_at"].isoformat(sep=" ")
        return task


class UserRepository(BaseRepository):
    table_name = "users"

    def initialize(self) -> None:
        with self.connection_factory() as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS users ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                "username TEXT NOT NULL UNIQUE, "
                "password_hash TEXT NOT NULL, "
                "email TEXT)"
            )
            columns = {row["name"] for row in conn.execute("PRAGMA table_info(users)")}
            if "email" not in columns:
                conn.execute("ALTER TABLE users ADD COLUMN email TEXT")

    def create_user(self, username: str, password_hash: str, email: str | None) -> int:
        return self.create({"username": username, "password_hash": password_hash, "email": email})

    def find_by_username(self, username: str):
        return self.find_one({"username": username})

    def notification_address(self, user_id: int) -> str | None:
        user = self.find_one({"id": user_id})
        if user is None:
            return None
        return user["email"] or user["username"]

